defmodule NativeElixirPdfUtilities.Validators.HtmlUrlIdnaValidator do
  @moduledoc false

  # UTS #46 nontransitional admission with CheckBidi and CheckJoiners, relaxed
  # hyphens/STD3/DNS length. The URL Standard's 2026-10-07 domain parser applies
  # this profile to non-ASCII decoded hosts. HtmlUrlValidator handles its ASCII
  # bypass separately. ACE labels reached through this profile are validated.
  # Pinned Unicode 16.0.0 data, Unicode License V3, distributed with
  # priv/licenses/unicode-character-properties-UNICODE-3.0.txt.
  # Sources: https://www.unicode.org/Public/idna/16.0.0/IdnaMappingTable.txt
  # https://www.unicode.org/Public/16.0.0/ucd/UnicodeData.txt
  # https://www.unicode.org/Public/16.0.0/ucd/extracted/DerivedJoiningType.txt
  # IdnaMappingTable.txt SHA256 6db2ef4ed35f3b3de74ebc2e00404a9607f76d499f576b8d4043cf14f1ed175c
  # UnicodeData.txt SHA256 ff58e5823bd095166564a006e47d111130813dcf8bf234ef79fa51a870edb48f
  # DerivedJoiningType.txt SHA256 6bd08b97da66b70ccfdab105a352de2984e02625239ec5695422c99b33d854f0
  @statuses {:valid, :deviation, :mapped, :ignored, :disallowed}
  @bidi_classes {:AL, :AN, :B, :BN, :CS, :EN, :ES, :ET, :FSI, :L, :LRE, :LRI, :LRO, :NSM, :ON,
                 :PDF, :PDI, :R, :RLE, :RLI, :RLO, :S, :WS}
  @joining_types {:C, :D, :L, :R, :T, :U}
  @data (for <<start::24, status::8, bidi::8, joining::8, flags::8, size::16,
               mapping::binary-size(size) <-
                 :zlib.uncompress(
                   Base.decode64!(
                     ""
                   )
                 )>> do
           {start, elem(@statuses, status), mapping, elem(@bidi_classes, bidi),
            elem(@joining_types, joining), flags}
         end)
        |> List.to_tuple()

  @doc "Validates and maps a domain for initial URL admission without DNS or resource access."
  @spec domain(binary()) :: {:ok, binary()} | :error
  def domain(source) do
    if String.valid?(source) do
      mapped =
        Enum.reduce_while(String.to_charlist(source), [], fn codepoint, output ->
          case properties(codepoint) do
            {_, status, _, _, _, _} when status in [:valid, :deviation] ->
              {:cont, [<<codepoint::utf8>> | output]}

            {_, :mapped, mapping, _, _, _} ->
              {:cont, [mapping | output]}

            {_, :ignored, _, _, _, _} ->
              {:cont, output}

            _ ->
              {:halt, :error}
          end
        end)

      if mapped == :error do
        :error
      else
        normalized = mapped |> Enum.reverse() |> IO.iodata_to_binary() |> String.normalize(:nfc)

        labels =
          Enum.reduce_while(String.split(normalized, "."), [], fn label, output ->
            decoded =
              case label do
                "xn--" <> payload ->
                  case decode_punycode(payload) do
                    {:ok, value} ->
                      if Enum.any?(value, &(&1 > 127)), do: {:ok, value}, else: :error

                    :error ->
                      :error
                  end

                _ ->
                  {:ok, String.to_charlist(label)}
              end

            case decoded do
              {:ok, codepoints} ->
                value = List.to_string(codepoints)
                first_properties = if codepoints == [], do: nil, else: properties(hd(codepoints))

                valid? =
                  String.normalize(value, :nfc) == value and
                    not String.starts_with?(value, "xn--") and
                    (is_nil(first_properties) or elem(first_properties, 5) not in [1, 3]) and
                    Enum.all?(codepoints, fn codepoint ->
                      codepoint != ?. and elem(properties(codepoint), 1) in [:valid, :deviation]
                    end) and valid_joiners?(codepoints)

                if valid?, do: {:cont, [codepoints | output]}, else: {:halt, :error}

              :error ->
                {:halt, :error}
            end
          end)

        if labels == :error do
          :error
        else
          bidi_domain? =
            Enum.any?(labels, fn label ->
              Enum.any?(label, &(elem(properties(&1), 3) in [:R, :AL, :AN]))
            end)

          if normalized != "" and
               (not bidi_domain? or Enum.all?(labels, &valid_bidi_label?/1)) do
            # Only admission is required. Unicode labels need no ACE re-encoding
            # here, and mapped ASCII numeric labels retain IPv4 host semantics.
            {:ok, labels |> Enum.reverse() |> Enum.map_join(".", &List.to_string/1)}
          else
            :error
          end
        end
      end
    else
      :error
    end
  end

  # Binary search the generated complete scalar-range table. It contains the
  # entire 0..0x10FFFF interval, including disallowed/unassigned code points.
  defp properties(codepoint) do
    properties(codepoint, 0, tuple_size(@data) - 1)
  end

  defp properties(codepoint, low, high) do
    middle = div(low + high + 1, 2)
    entry = elem(@data, middle)

    cond do
      low == high -> entry
      elem(entry, 0) > codepoint -> properties(codepoint, low, middle - 1)
      true -> properties(codepoint, middle, high)
    end
  end

  # RFC 5892 Appendix A.1/A.2. Joiners need a preceding virama, or, for
  # ZWNJ only, the prescribed joining-type context ignoring transparent marks.
  defp valid_joiners?(codepoints, previous_virama? \\ false, left \\ nil) do
    case codepoints do
      [] ->
        true

      [codepoint | rest] ->
        {_, _, _, _, joining, flags} = properties(codepoint)

        valid? =
          cond do
            codepoint not in [0x200C, 0x200D] or previous_virama? ->
              true

            codepoint == 0x200D or left not in [:L, :D] ->
              false

            true ->
              # Keep the preceding nontransparent type while traversing the
              # label, and stop the forward scan at the next such type. This
              # avoids copying/scanning the whole label for every joiner.
              Enum.find_value(rest, fn next ->
                type = elem(properties(next), 4)
                if type != :T, do: type
              end) in [:R, :D]
          end

        valid? and
          valid_joiners?(
            rest,
            Bitwise.band(flags, 2) != 0,
            if(joining == :T, do: left, else: joining)
          )
    end
  end

  # RFC 5893 section 2 applies to every nonempty label of a Bidi domain.
  defp valid_bidi_label?(codepoints) do
    if codepoints == [] do
      true
    else
      classes = Enum.map(codepoints, &elem(properties(&1), 3))
      last = classes |> Enum.reverse() |> Enum.drop_while(&(&1 == :NSM)) |> List.first()

      case hd(classes) do
        direction when direction in [:R, :AL] ->
          Enum.all?(classes, &(&1 in [:R, :AL, :AN, :EN, :ES, :CS, :ET, :ON, :BN, :NSM])) and
            last in [:R, :AL, :EN, :AN] and not (:EN in classes and :AN in classes)

        :L ->
          Enum.all?(classes, &(&1 in [:L, :EN, :ES, :CS, :ET, :ON, :BN, :NSM])) and
            last in [:L, :EN]

        _ ->
          false
      end
    end
  end

  # RFC 3492 section 6.2. Only decoding is needed for validity; all arithmetic
  # bounds below follow the maximum Unicode scalar, not a configurable budget.
  defp decode_punycode(payload) do
    # Punycode preserves every basic ASCII code point before its final
    # delimiter, including '_' under the relaxed URL STD3 profile. Only the
    # encoded suffix uses the a-z/0-9 digit alphabet checked below.
    if Regex.match?(~r/\A[\x00-\x7f]+\z/, payload) do
      {basic, encoded} =
        case :binary.matches(payload, "-") do
          [] ->
            {[], payload}

          matches ->
            {offset, _} = List.last(matches)

            {payload |> binary_part(0, offset) |> String.to_charlist(),
             binary_part(payload, offset + 1, byte_size(payload) - offset - 1)}
        end

      decode_punycode(encoded, basic, 128, 0, 72)
    else
      :error
    end
  end

  defp decode_punycode(encoded, output, codepoint, index, bias) do
    if encoded == "" do
      {:ok, output}
    else
      count = length(output) + 1

      with {:ok, next_index, remaining} <-
             punycode_integer(encoded, index, 1, 36, bias, 0x10FFFF * count),
           next_codepoint = codepoint + div(next_index, count),
           true <- next_codepoint <= 0x10FFFF and next_codepoint not in 0xD800..0xDFFF do
        next_bias = punycode_bias(next_index - index, count, index == 0)
        insertion = rem(next_index, count)

        decode_punycode(
          remaining,
          List.insert_at(output, insertion, next_codepoint),
          next_codepoint,
          insertion + 1,
          next_bias
        )
      else
        _ -> :error
      end
    end
  end

  defp punycode_integer(encoded, index, weight, step, bias, maximum) do
    case encoded do
      <<digit, remaining::binary>> ->
        digit =
          cond do
            digit in ?a..?z -> digit - ?a
            digit in ?0..?9 -> digit - ?0 + 26
            true -> :error
          end

        threshold = min(max(step - bias, 1), 26)

        cond do
          digit == :error ->
            :error

          index + digit * weight > maximum ->
            :error

          digit < threshold ->
            {:ok, index + digit * weight, remaining}

          true ->
            punycode_integer(
              remaining,
              index + digit * weight,
              weight * (36 - threshold),
              step + 36,
              bias,
              maximum
            )
        end

      _ ->
        :error
    end
  end

  defp punycode_bias(delta, count, first?) do
    delta = if first?, do: div(delta, 700), else: div(delta, 2)
    delta = delta + div(delta, count)
    punycode_bias_scale(delta, 0)
  end

  defp punycode_bias_scale(delta, offset) do
    if delta > 455,
      do: punycode_bias_scale(div(delta, 35), offset + 36),
      else: offset + div(36 * delta, delta + 38)
  end
end
